<script lang="ts">
  import {onMount} from 'svelte';
  import type {ChartController} from '../../lib/chart/controller';
  import {APPEARANCE_PRESETS,DEFAULT_APPEARANCE,appearancePreset,deriveOverlaySurface,type AppearancePresetId,type ChartAppearance} from '../../lib/chart/appearance';
  import {t} from '../../lib/i18n';
  import ToolIcon from '../drawing/ToolIcon.svelte';
  import ColorField from './ColorField.svelte';
  import {uiThemeFor} from '../../lib/ui/theme';
  let {controller,onClose}:{controller:ChartController;onClose:()=>void}=$props();
  type Tab='theme'|'candles'|'canvas'|'scales';
  type ColorKey='upColor'|'downColor'|'borderUpColor'|'borderDownColor'|'wickUpColor'|'wickDownColor'|'lineColor'|'background'|'backgroundEnd'|'gridColor'|'textColor'|'separatorColor'|'crosshairColor'|'watermarkColor';
  const tabs:{id:Tab;label:string}[]=[{id:'theme',label:'主题'},{id:'candles',label:'蜡烛图'},{id:'canvas',label:'画布'},{id:'scales',label:'刻度与光标'}];
  const types:{id:ChartAppearance['chartType'];label:string}[]=[{id:'candles',label:'实心蜡烛'},{id:'hollow',label:'空心蜡烛'},{id:'bars',label:'美国线'},{id:'line',label:'价格折线'}];
  const colors:ColorKey[]=['upColor','downColor','borderUpColor','borderDownColor','wickUpColor','wickDownColor','lineColor','background','backgroundEnd','gridColor','textColor','separatorColor','crosshairColor','watermarkColor'];
  const candles=[{o:74,c:57,h:46,l:82},{o:57,c:64,h:50,l:73},{o:64,c:44,h:33,l:70},{o:56,c:51,h:36,l:61},{o:51,c:32,h:21,l:56},{o:24,c:30,h:20,l:41},{o:30,c:29,h:18,l:45},{o:29,c:35,h:22,l:44}];
  let dialog:HTMLDialogElement;
  let active=$state<Tab>('theme'),draft=$state<ChartAppearance>({...DEFAULT_APPEARANCE}),invalidColors=$state<Record<string,boolean>>({}),colorReset=$state(0),storageError=$state(false),horizontalTabs=$state(false);
  let original:ChartAppearance|undefined,committed=false,restored=false,closed=false;
  const invalid=$derived(Object.values(invalidColors).some(Boolean));
  const candleMode=$derived(draft.chartType==='candles'||draft.chartType==='hollow');
  function update<K extends keyof ChartAppearance>(key:K,value:ChartAppearance[K]){draft={...draft,[key]:value,preset:colors.includes(key as ColorKey)?'custom':draft.preset};storageError=false;controller.previewAppearance({...draft});}
  function valid(key:string,value:boolean){if(invalidColors[key]===!value)return;invalidColors={...invalidColors,[key]:!value};}
  function preset(id:AppearancePresetId){const palette=appearancePreset(id),next={...draft,preset:id,overlayOpacity:palette.overlayOpacity};for(const key of colors)next[key]=palette[key];draft=next;colorReset++;invalidColors={};storageError=false;controller.previewAppearance({...draft});}
  function reset(){draft={...DEFAULT_APPEARANCE};colorReset++;invalidColors={};storageError=false;controller.previewAppearance({...draft});}
  function restore(){if(original&&!committed&&!restored){controller.restoreAppearance({...original});restored=true;}}
  function cancel(){if(closed)return;closed=true;restore();dialog?.close();onClose();}
  function save(){if(invalid||closed)return;if(!controller.commitAppearance({...draft})){storageError=true;return;}committed=true;closed=true;dialog.close();onClose();}
  function backdrop(event:MouseEvent){if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)cancel();}
  function tabKey(event:KeyboardEvent){const index=tabs.findIndex(tab=>tab.id===active);let next=-1;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;if(next<0)return;event.preventDefault();active=tabs[next].id;dialog.querySelector<HTMLButtonElement>(`#appearance-tab-${active}`)?.focus();}
  onMount(()=>{const previous=document.activeElement instanceof HTMLElement?document.activeElement:null,query=matchMedia('(max-width:650px)');const orient=()=>horizontalTabs=query.matches;orient();query.addEventListener('change',orient);original={...controller.getAppearance()};draft={...original};dialog.showModal();dialog.querySelector<HTMLButtonElement>('[role="tab"][aria-selected="true"]')?.focus();return()=>{query.removeEventListener('change',orient);restore();dialog?.close();if(previous?.isConnected&&!document.querySelector('dialog[open]'))previous.focus();};});
  const dash=(style:string)=>style==='dashed'?'5 4':style==='dotted'?'1 4':undefined;
</script>

{#snippet preview(a:ChartAppearance,id:string,compact=false)}
  {@const surface=deriveOverlaySurface(a)}
  {@const ui=uiThemeFor(a)}
  <svg class="chart-preview" viewBox="0 0 300 116" role="img" aria-label={$t('样式预览')}>
    <defs><linearGradient id={`appearance-gradient-${id}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color={a.background}/><stop offset="100%" stop-color={a.backgroundEnd}/></linearGradient></defs>
    <rect width="300" height="116" fill={a.backgroundMode==='gradient'?`url(#appearance-gradient-${id})`:a.background}/>
    <g stroke={a.gridColor} opacity={a.gridOpacity} stroke-width=".7" stroke-dasharray={dash(a.gridStyle)}>
      {#if a.grid==='both'||a.grid==='horizontal'}{#each [24,48,72,96] as y}<line x1="0" x2="267" y1={y} y2={y}/>{/each}{/if}
      {#if a.grid==='both'||a.grid==='vertical'}{#each [40,88,136,184,232] as x}<line x1={x} x2={x} y1="0" y2="116"/>{/each}{/if}
    </g>
    {#if a.watermark&&!compact}<text x="130" y="62" text-anchor="middle" fill={a.watermarkColor} opacity={a.watermarkOpacity} font-size={Math.min(30,a.watermarkFontSize/2)} font-family="sans-serif">{a.watermarkText.slice(0,14)||'SYMBOL'}</text>{/if}
    <g>
      {#each candles as candle,i}
        {@const x=22+i*30}
        {@const up=a.chartType==='hollow'||a.colorBy==='previous-close'?candle.c<=(candles[i-1]?.c??candles[0].o):candle.c<=candle.o}
        {@const bodyColor=up?a.upColor:a.downColor}
        {@const wickColor=up?a.wickUpColor:a.wickDownColor}
        {@const borderColor=up?a.borderUpColor:a.borderDownColor}
        {@const hollow=a.chartType==='hollow'&&candle.c<=candle.o}
        <rect x={x-6} y={107-(i%3+1)*5} width="12" height={(i%3+1)*5} fill={bodyColor} opacity={a.volumeOpacity}/>
        {#if a.chartType==='bars'}
          {#if a.showWicks}<path d={`M${x} ${candle.h}V${candle.l}M${x-6} ${candle.o}H${x}M${x} ${candle.c}H${x+6}`} fill="none" stroke={wickColor} stroke-width="1.5"/>{/if}
        {:else if a.chartType!=='line'}
          {#if a.showWicks}<path d={`M${x} ${candle.h}V${Math.min(candle.o,candle.c)}M${x} ${Math.max(candle.o,candle.c)}V${candle.l}`} stroke={wickColor} stroke-width="1.2"/>{/if}
          {#if a.showBodies||a.showBorders}<rect x={x-6} y={Math.min(candle.o,candle.c)} width="12" height={Math.max(1,Math.abs(candle.o-candle.c))} rx={Math.min(a.candleRadius,4,Math.abs(candle.o-candle.c)/2)} fill={a.showBodies&&!hollow?bodyColor:'none'} stroke={a.showBorders?borderColor:'none'} stroke-width="1.2"/>{/if}
        {/if}
      {/each}
      {#if a.chartType==='line'}<polyline points={candles.map((c,i)=>`${22+i*30},${c.c}`).join(' ')} fill="none" stroke={a.lineColor} stroke-width={a.lineWidth}/>{/if}
    </g>
    {#if !compact}<rect x="8" y="8" width="96" height="15" rx="3" fill={surface.glassBg} stroke={surface.glassBorder}/><text x="14" y="18" fill={surface.glassText} font-size="7.5" font-family="sans-serif" font-weight="600">VOL · MA(5,10,20)</text>{/if}
    <line x1="267" x2="267" y1="0" y2="116" stroke={a.separatorColor}/>
    {#if compact}<g aria-hidden="true"><rect width="15" height="116" fill={ui.panel}/><line x1="15" x2="15" y1="0" y2="116" stroke={ui.lineStrong}/>{#each [14,28,42,56] as y,index}<rect x="4.5" y={y-3} width="6" height="6" rx="1.5" fill={index===0?ui.accent:ui.textMuted}/>{/each}</g>{/if}
    {#if !compact}<g font-family="monospace" font-size={Math.max(7,a.scaleFontSize-3)} fill={a.textColor}><text x="274" y="26">120</text><text x="274" y="50">110</text><text x="274" y="74">100</text><text x="274" y="98">90</text></g>{/if}
    {#if a.lastPriceLine}<line x1="0" x2="267" y1="35" y2="35" stroke={a.chartType==='line'?a.lineColor:a.downColor} stroke-width=".6" stroke-dasharray="3 3"/>{/if}
    {#if a.lastPriceLabel&&!compact}<rect x="268" y="29" width="32" height="12" fill={a.chartType==='line'?a.lineColor:a.downColor}/><text x="272" y="38" fill={a.background} font-size="8" font-family="monospace">116.2</text>{/if}
    {#if a.crosshairVisible&&!compact}<path d="M172 0V116M0 66H267" stroke={a.crosshairColor} stroke-width=".7" stroke-dasharray={dash(a.crosshairStyle)} fill="none"/>{/if}
  </svg>
{/snippet}

{#snippet color(key:ColorKey,label:string,disabled=false)}
  <ColorField id={`appearance-${key}`} label={$t(label)} value={draft[key]} resetKey={colorReset} {disabled} onchange={value=>update(key,value)} onvalidity={value=>valid(key,value)}/>
{/snippet}

{#snippet lineStyle(key:'gridStyle'|'crosshairStyle',label:string,disabled=false)}
  <label class="control"><span>{$t(label)}</span><select id={`appearance-${key}`} value={draft[key]} {disabled} onchange={event=>update(key,event.currentTarget.value as ChartAppearance[typeof key])}><option value="solid">{$t('实线')}</option><option value="dashed">{$t('虚线')}</option><option value="dotted">{$t('点线')}</option></select></label>
{/snippet}

{#snippet percent(key:'volumeOpacity'|'overlayOpacity'|'gridOpacity'|'watermarkOpacity',label:string,max=1,disabled=false,min=0)}
  <label class="control range-control" for={`appearance-${key}`}><span>{$t(label)}<output for={`appearance-${key}`}>{Math.round(draft[key]*100)}%</output></span><input id={`appearance-${key}`} aria-label={$t(label)} type="range" {min} {max} step="0.01" value={draft[key]} {disabled} oninput={event=>update(key,Number(event.currentTarget.value))}/></label>
{/snippet}

<dialog bind:this={dialog} class="appearance-dialog" aria-labelledby="appearance-title" aria-describedby="appearance-description" oncancel={event=>{event.preventDefault();cancel();}} onclick={backdrop}>
  <header class="appearance-header"><div><h2 id="appearance-title">{$t('图表外观')}</h2><p id="appearance-description">{$t('调整立即预览，保存后保留。')}</p></div><button type="button" class="close-button" aria-label={$t('关闭外观设置')} onclick={cancel}><ToolIcon name="close" size={17}/></button></header>
  <div class="appearance-body">
    <div class="appearance-tabs" role="tablist" aria-orientation={horizontalTabs?'horizontal':'vertical'} aria-label={$t('图表外观设置')}>
      {#each tabs as tab}<button type="button" role="tab" id={`appearance-tab-${tab.id}`} aria-controls={`appearance-panel-${tab.id}`} aria-selected={active===tab.id} tabindex={active===tab.id?0:-1} onclick={()=>active=tab.id} onkeydown={tabKey}>{$t(tab.label)}</button>{/each}
    </div>
    <div class="settings-workspace">
      <aside class="live-preview" aria-label={$t('样式预览')}><div class="preview-copy"><strong>{$t('样式预览')}</strong><span>{$t('示例 K 线 · 非市场数据')}</span></div>{@render preview(draft,'live')}</aside>
      <div class="settings-scroll">
        <div id="appearance-panel-theme" role="tabpanel" aria-labelledby="appearance-tab-theme" hidden={active!=='theme'} tabindex="0">
          <div class="section-heading"><h3>{$t('工作区主题')}</h3>{#if draft.preset==='custom'}<span class="custom-badge">{$t('当前为自定义配色')}</span>{/if}</div>
          <p class="section-description">{$t('图表与工具栏、面板、菜单一起切换；保留图表类型、显示开关与其他偏好。')}</p>
          <div class="appearance-preset-grid">{#each APPEARANCE_PRESETS as item}<button type="button" class="preset-card" class:selected={draft.preset===item.id} aria-pressed={draft.preset===item.id} onclick={()=>preset(item.id)}>{@render preview(appearancePreset(item.id),item.id,true)}<span class="preset-caption"><strong>{$t(item.name)}</strong><span class="selection-mark" aria-hidden="true">{draft.preset===item.id?'✓':''}</span><small>{$t(item.description)}</small></span></button>{/each}</div>
        </div>
        <div id="appearance-panel-candles" role="tabpanel" aria-labelledby="appearance-tab-candles" hidden={active!=='candles'} tabindex="0">
          <h3>{$t('图表类型')}</h3>
          <div class="chart-types" role="group" aria-label={$t('图表类型')}>{#each types as type}<button type="button" class:selected={draft.chartType===type.id} aria-pressed={draft.chartType===type.id} onclick={()=>update('chartType',type.id)}><svg viewBox="0 0 30 24" width="30" height="24" aria-hidden="true">{#if type.id==='line'}<path d="M2 19L8 13L13 16L19 6L23 10L28 3" fill="none" stroke="currentColor" stroke-width="1.7"/>{:else if type.id==='bars'}<path d="M8 2V20M3 7H8M8 15H13M22 4V23M17 18H22M22 8H27" fill="none" stroke="currentColor" stroke-width="1.5"/>{:else}<path d="M8 1V23M22 2V22" stroke="currentColor" stroke-width="1.2"/><rect x="4" y="6" width="8" height="10" fill={type.id==='hollow'?'var(--bg-panel)':'currentColor'} stroke="currentColor"/><rect x="18" y="9" width="8" height="10" fill="currentColor" stroke="currentColor"/>{/if}</svg><span>{$t(type.label)}</span></button>{/each}</div>
          <label class="control color-rule"><span>{$t('K 线圆角')}</span><select value={draft.candleRadius} disabled={!candleMode} onchange={event=>update('candleRadius',Number(event.currentTarget.value))}>{#each [0,1,1.5,2,3,4] as radius}<option value={radius}>{radius===0?$t('直角'):`${radius} px`}</option>{/each}</select></label>
          <label class="control color-rule"><span>{$t('涨跌着色依据')}</span><select value={draft.chartType==='hollow'?'previous-close':draft.colorBy} disabled={draft.chartType==='hollow'||draft.chartType==='line'} onchange={event=>update('colorBy',event.currentTarget.value as ChartAppearance['colorBy'])}><option value="open-close">{$t('收盘价与开盘价')}</option><option value="previous-close">{$t('收盘价与前一收盘价')}</option></select></label>
          {#if draft.chartType==='hollow'}<p class="note">{$t('空心蜡烛：颜色比较前一收盘价；空心表示收盘价不低于开盘价，实心表示收盘价低于开盘价。')}</p>{:else if draft.chartType==='bars'}<p class="note">{$t('美国线使用影线颜色绘制开、高、低、收。')}</p>{:else if draft.chartType==='line'}<p class="note">{$t('折线模式使用收盘价连接。')}</p>{/if}
          <div class="candle-colors">
            <div class="color-row"><label class="toggle-label"><input type="checkbox" checked={draft.showBodies} disabled={!candleMode} onchange={event=>update('showBodies',event.currentTarget.checked)}/><span>{$t('实体')}</span></label>{@render color('upColor','上涨实体颜色',!candleMode||!draft.showBodies)}{@render color('downColor','下跌实体颜色',!candleMode||!draft.showBodies)}</div>
            <div class="color-row"><label class="toggle-label"><input type="checkbox" checked={draft.showBorders} disabled={!candleMode} onchange={event=>update('showBorders',event.currentTarget.checked)}/><span>{$t('边框')}</span></label>{@render color('borderUpColor','上涨边框颜色',!candleMode||!draft.showBorders)}{@render color('borderDownColor','下跌边框颜色',!candleMode||!draft.showBorders)}</div>
            <div class="color-row"><label class="toggle-label"><input type="checkbox" checked={draft.showWicks} disabled={draft.chartType==='line'} onchange={event=>update('showWicks',event.currentTarget.checked)}/><span>{$t('影线')}</span></label>{@render color('wickUpColor','上涨影线颜色',draft.chartType==='line'||!draft.showWicks)}{@render color('wickDownColor','下跌影线颜色',draft.chartType==='line'||!draft.showWicks)}</div>
          </div>
          <div class="field-grid divided">{@render color('lineColor','折线颜色',draft.chartType!=='line')}<label class="control"><span>{$t('折线宽度')}</span><select value={draft.lineWidth} disabled={draft.chartType!=='line'} onchange={event=>update('lineWidth',Number(event.currentTarget.value))}>{#each [1,2,3,4] as width}<option value={width}>{width} px</option>{/each}</select></label>{@render percent('volumeOpacity','成交量透明度')}</div>
        </div>
        <div id="appearance-panel-canvas" role="tabpanel" aria-labelledby="appearance-tab-canvas" hidden={active!=='canvas'} tabindex="0">
          <h3>{$t('画布背景')}</h3><div class="field-grid"><label class="control full"><span>{$t('背景模式')}</span><select value={draft.backgroundMode} onchange={event=>update('backgroundMode',event.currentTarget.value as ChartAppearance['backgroundMode'])}><option value="solid">{$t('纯色')}</option><option value="gradient">{$t('渐变')}</option></select></label>{@render color('background','背景颜色')}{@render color('backgroundEnd','渐变终点颜色',draft.backgroundMode!=='gradient')}{@render percent('overlayOpacity','浮层毛玻璃不透明度',.96,false,.35)}</div>
          <h3 class="divided">{$t('网格')}</h3><div class="field-grid"><label class="control"><span>{$t('网格方向')}</span><select value={draft.grid} onchange={event=>update('grid',event.currentTarget.value as ChartAppearance['grid'])}><option value="both">{$t('水平和垂直')}</option><option value="horizontal">{$t('仅水平')}</option><option value="vertical">{$t('仅垂直')}</option><option value="none">{$t('不显示网格')}</option></select></label>{@render lineStyle('gridStyle','网格线型',draft.grid==='none')}{@render color('gridColor','网格颜色',draft.grid==='none')}{@render percent('gridOpacity','网格透明度',1,draft.grid==='none')}</div>
          <div class="section-heading divided"><h3>{$t('水印')}</h3><label class="toggle-label"><input type="checkbox" checked={draft.watermark} onchange={event=>update('watermark',event.currentTarget.checked)}/><span>{$t('显示水印')}</span></label></div><div class="field-grid"><label class="control full"><span>{$t('水印文字')}</span><input type="text" maxlength="64" value={draft.watermarkText} disabled={!draft.watermark} placeholder={$t('留空使用当前交易品种')} oninput={event=>update('watermarkText',event.currentTarget.value)}/></label>{@render color('watermarkColor','水印颜色',!draft.watermark)}{@render percent('watermarkOpacity','水印透明度',.5,!draft.watermark)}<label class="control" for="appearance-watermark-size"><span>{$t('水印字号')}<output for="appearance-watermark-size">{draft.watermarkFontSize} px</output></span><input id="appearance-watermark-size" aria-label={$t('水印字号')} type="range" min="16" max="96" step="1" value={draft.watermarkFontSize} disabled={!draft.watermark} oninput={event=>update('watermarkFontSize',Number(event.currentTarget.value))}/></label></div>
        </div>
        <div id="appearance-panel-scales" role="tabpanel" aria-labelledby="appearance-tab-scales" hidden={active!=='scales'} tabindex="0">
          <h3>{$t('刻度与标签')}</h3><div class="field-grid">{@render color('textColor','刻度文字颜色')}<label class="control"><span>{$t('刻度字号')}</span><select value={draft.scaleFontSize} onchange={event=>update('scaleFontSize',Number(event.currentTarget.value))}>{#each [10,11,12,13,14,15,16] as size}<option value={size}>{size} px</option>{/each}</select></label>{@render color('separatorColor','分隔线颜色')}</div>
          <div class="toggle-list"><label class="toggle-label"><input type="checkbox" checked={draft.lastPriceLine} onchange={event=>update('lastPriceLine',event.currentTarget.checked)}/><span>{$t('显示最新价格线')}</span></label><label class="toggle-label"><input type="checkbox" checked={draft.lastPriceLabel} onchange={event=>update('lastPriceLabel',event.currentTarget.checked)}/><span>{$t('显示最新价格标签')}</span></label></div>
          <div class="section-heading divided"><h3>{$t('十字光标')}</h3><label class="toggle-label"><input type="checkbox" checked={draft.crosshairVisible} onchange={event=>update('crosshairVisible',event.currentTarget.checked)}/><span>{$t('显示十字光标')}</span></label></div><div class="field-grid">{@render color('crosshairColor','光标颜色',!draft.crosshairVisible)}{@render lineStyle('crosshairStyle','光标线型',!draft.crosshairVisible)}</div>
        </div>
      </div>
    </div>
  </div>
  {#if storageError||invalid}<div class="appearance-alert" role="alert">{$t(storageError?'无法保存到浏览器。预览仍然有效；请允许此站点使用本地存储后重试，或取消恢复原外观。':'有颜色输入无效，请修正后保存。')}</div>{/if}
  <footer class="appearance-footer"><button type="button" class="reset-button" onclick={reset}>{$t('恢复默认')}</button><div><button type="button" class="cancel-button" onclick={cancel}>{$t('取消')}</button><button type="button" class="save-button" disabled={invalid} onclick={save}>{$t(storageError?'重试保存':'保存外观')}</button></div></footer>
</dialog>

<style>
